import { useEffect, useRef, useState, type ReactNode } from 'react';
import { readStored, writeStored } from '../stappen/storage';
import { routes, routeKeys, starterPackages, fields, cycle, learningSituations, promptTips, learningRecap, type Route } from './data';
import { downloadReport } from './pdf';
import { writeAnswer } from '../vragen/answers';
import { fieldPanes, recordVisit, stepNumber, timelineEntries } from './progress';
import './vibe.css';
import choiceStyles from '../stappen/Keuze.module.css';
import { celebrateMilestone } from '../stappen/confetti';

type Work = Record<string, string>;
let current: Work = {};
let initialized = false;
const eventName = 'vibecoding-work-change';
const moduleId = 'vibecoding';
function update(patch: Work) { for (const [key, value] of Object.entries(patch)) { if (fields[key] && value.trim()) writeAnswer(moduleId, `vibe-${key}`, { kind: 'reflection', question: fields[key], answer: value }); } current = { ...current, ...patch }; writeStored(moduleId, 'werk', JSON.stringify(current)); window.dispatchEvent(new Event(eventName)); }
function go(pane: string) { window.location.hash = `stap-${stepNumber(pane)}`; }
export default function Vibe({ pane }: { pane: string }) {
  const rootRef = useRef<HTMLDivElement>(null);
  const [work, setWork] = useState<Work>({});
  const [notice, setNotice] = useState('');
  const [downloading, setDownloading] = useState(false);
  const [selected, setSelected] = useState(0);
  const [needAnswer, setNeedAnswer] = useState<number | null>(null);
  const [order, setOrder] = useState([2, 0, 4, 1, 3]);
  const [dragged, setDragged] = useState<number | null>(null);
  useEffect(() => {
    if (!initialized) { try { const parsed: unknown = JSON.parse(readStored(moduleId, 'werk') || '{}'); if (parsed && typeof parsed === 'object') current = Object.fromEntries(Object.entries(parsed).filter((entry): entry is [string, string] => typeof entry[1] === 'string')); } catch { current = {}; } initialized = true; }
    const sync = () => { setWork({ ...current }); if (pane === 'situatie' && current.quizAnswer !== undefined) setNeedAnswer(Number(current.quizAnswer)); };
    if (pane === 'volgorde' && current.cycleOrder) { try { const saved: unknown = JSON.parse(current.cycleOrder); if (Array.isArray(saved) && saved.length === 5 && saved.every(n => Number.isInteger(n) && n >= 0 && n < 5) && new Set(saved).size === 5) setOrder(saved as number[]); } catch { /* Keep the starting order. */ } }
    sync(); window.addEventListener(eventName, sync);
    return () => window.removeEventListener(eventName, sync);
  }, [pane]);
  useEffect(() => {
    if (pane !== 'spectrum' || !rootRef.current) return;
    const section = rootRef.current.closest('[data-step]');
    if (!section) return;
    const observer = new MutationObserver(() => { if (!section.hasAttribute('hidden')) { setSelected(0); } });
    observer.observe(section, { attributes: true, attributeFilter: ['hidden'] });
    return () => observer.disconnect();
  }, [pane]);
  useEffect(() => {
    const section = rootRef.current?.closest('[data-step]');
    if (!section) return;
    const track = () => { if (!section.hasAttribute('hidden')) recordVisit(pane); };
    track();
    const observer = new MutationObserver(track);
    observer.observe(section, { attributes: true, attributeFilter: ['hidden'] });
    return () => observer.disconnect();
  }, [pane]);
  const materialComplete = work.source === 'Eigen materiaal' || (work.source === 'Startpakket' && Boolean(work.material?.trim() && starterPackages.some(pack => pack.id === work.packageId && (work.solutionKind === 'eigen' || pack.route === work.solutionKind))));
  const choiceComplete = Boolean((work.solutionKind === 'eigen' || Object.hasOwn(routes, work.solutionKind || '')) && (work.solutionKind !== 'eigen' || (work.materialReady === 'ja' && work.basicReady === 'ja')));
  const solutionComplete = choiceComplete && Boolean(work.help?.trim());
  useEffect(() => { if (pane === 'situatie' || pane === 'kiezen' || pane === 'oplossing' || pane === 'volgorde' || pane === 'pakket') document.dispatchEvent(new Event('step-validity-change')); }, [pane, needAnswer, choiceComplete, solutionComplete, materialComplete, order, work.solutionKind, work.basicReady, work.materialReady]);
  useEffect(() => {
    const root = rootRef.current;
    const milestone = pane === 'situatie' && needAnswer === 1 ? 'noor-behoefte'
      : pane === 'volgorde' && order.every((item, i) => item === i) ? 'bouwvolgorde'
      : pane === 'verslag' && Object.entries(fields).every(([key]) => (key === 'material' && work.source !== 'Startpakket') || Boolean(work[key]?.trim())) && solutionComplete && materialComplete && work.quizAnswer === '1' && work.cycleOrder === '[0,1,2,3,4]' ? 'leerpad-afgerond' : null;
    if (!root || !milestone) return;
    const observer = new IntersectionObserver(entries => {
      if (entries.some(entry => entry.isIntersecting)) celebrateMilestone(root, milestone);
    });
    observer.observe(root);
    return () => observer.disconnect();
  }, [pane, needAnswer, order, work, solutionComplete, materialComplete]);
  const columns = (copy: ReactNode, actions: ReactNode) => <div className="v-columns"><div className="v-copy">{copy}</div><div className="v-actions">{actions}</div></div>;
  const choiceCards = (name: string, question: string, options: [string, string][], value: string, onChoose: (value: string) => void) => <fieldset className={`${choiceStyles.group} v-choice-cards`}><legend className={choiceStyles.question}>{question}</legend><div className={choiceStyles.options}>{options.map(([key, label]) => <label key={key} className={choiceStyles.option}><input type="radio" className={choiceStyles.radio} name={`v-choice-${name}`} value={key} checked={value === key} onChange={() => onChoose(key)} /><span>{label}</span></label>)}</div></fieldset>;
  const route: Route | undefined = (Object.keys(routes) as Route[]).find(key => key === work.solutionKind);
  const chosen = route ? routes[route] : null;
  const packageRoute = route || routeKeys.find(key => key === work.packageRoute);
  const availablePackages = starterPackages.filter(pack => pack.route === packageRoute);
  const chosenPackage = availablePackages.find(pack => pack.id === work.packageId);
  const field = (id: string, hint?: string, rows = 3, disabled = false) => <div className="v-field" key={id}><label htmlFor={`v-${id}`}>{fields[id] || id}</label>{hint && (hint.startsWith("Bijvoorbeeld:") && pane !== 'behoefte' ? <details className="v-example"><summary>Bekijk een voorbeeldantwoord</summary><div className="v-callout">{hint}</div></details> : <p className="v-small">{hint}</p>)}<textarea id={`v-${id}`} rows={rows} disabled={disabled} value={work[id] || ''} onChange={e => update({ [id]: e.target.value })} /></div>;
  const copy = async (value: string) => { try { await navigator.clipboard.writeText(value); setNotice('Gekopieerd. Plak dit in jouw AI-chat.'); } catch { setNotice('Selecteer de prompttekst en kopieer met Ctrl+C (of ⌘C).'); } };
  const prompt = (text: string, tips: string[] = []) => <><textarea className="v-prompt" rows={6} readOnly value={text} aria-label="Opdracht om naar AI te kopiëren" /><button onClick={() => void copy(text)}>Kopieer opdracht</button><p role="status" className="v-small">{notice}</p>{tips.length > 0 && <details className="v-prompt-tips"><summary>Wat kun je hiervan leren?</summary><ul>{tips.map(tip => <li key={tip}>{tip}</li>)}</ul></details>}</>;
  const handoff = (text: string) => <p className="v-handoff"><strong>AI-chat → terug naar dit leerpad</strong><span>{text}</span></p>;
  const testExamples: Record<string, [string, string, string]> = {
    woorden: ['Klik op ‘Toon vertaling’ als je die knop hebt. Verschijnt de vertaling pas na je klik? Ga naar een volgend woord. Verandert het woord?', 'Vergelijk enkele vertalingen met je woordenlijst. Vul bewust een juiste en een foute vertaling in. Worden die correct nagekeken?', 'Laat een antwoord leeg en controleer het. Klik daarna snel twee keer op controleren. Blijft de score kloppen?'],
    oefenen: ['Klik op een hint of oplossing als je die knoppen hebt. Verschijnt de juiste hulp? Ga naar de volgende oefening. Krijg je een nieuwe opgave?', 'Vergelijk een oplossing en de tussenstappen met je cursus. Probeer bewust een juist en een fout antwoord. Kloppen de feedback en berekeningen?', 'Controleer zonder een antwoord in te vullen. Klik daarna snel twee keer op dezelfde knop. Blijft je oefentool goed werken?'],
    mondeling: ['Vraag een volgende oefenvraag. Verandert de vraag? Open daarna de checklist als je die hebt. Verschijnen de controlepunten?', 'Vergelijk de oefenvragen en controlepunten met je leerstof. Helpen de controlepunten om je antwoord te beoordelen, ook als je het anders verwoordt?', 'Klik snel twee keer op een nieuwe vraag. Open dezelfde checklist twee keer. Blijven de vraag en de controlepunten bij elkaar horen?'],
    werkwijze: ['Open een stap en vink die af als dat kan. Verschijnt de juiste uitleg? Kun je opnieuw beginnen? Als je stappen kunt verplaatsen, probeer dat ook.', 'Vergelijk de stappen, hun volgorde en uitleg met je materiaal. Ontbreekt er een stap? Als je volgordes kunt controleren, probeer dan een juiste en een foute volgorde.', 'Klik op controleren zonder stappen te verplaatsen. Begin opnieuw nadat je enkele stappen hebt verplaatst. Kun je weer normaal oefenen?'],
    planner: ['Voeg een taak toe, verplaats die als dat kan en vink ze af. Kloppen taaknaam en tijd? Kun je de taak ook weer openzetten?', 'Vergelijk de planning met je taken en beschikbare tijd. Past alles vóór de deadline? Zijn er dubbele taken of overlappende blokken? Kloppen de totalen?', 'Voeg een taak toe die niet meer in de beschikbare tijd past. Probeer ook een lege taak of een eindtijd vóór de begintijd. Geeft je planner een duidelijke melding?'],
    tijdlijn: ['Klik op gebeurtenissen. Opent telkens de bijbehorende uitleg? Kun je ze weer sluiten? Werkt de volgorde van vroeg naar laat?', 'Vergelijk datums, gebeurtenissen en uitleg met je materiaal. Staat elke gebeurtenis op de juiste plaats? Hoort de juiste uitleg bij elke datum?', 'Open en sluit dezelfde gebeurtenis snel twee keer. Als je datums kunt toevoegen, probeer dan twee gebeurtenissen op dezelfde datum. Blijft alles leesbaar?'],
    algemeen: ['Klik op een knop. Gebeurt er wat je volgens je bouwplan verwachtte? Probeer ook opnieuw te beginnen als je die functie hebt.', 'Vergelijk een vraag, antwoord of uitleg met je leerstof. Klopt de inhoud? Als je iets kunt invullen, probeer dan bewust een juist en een fout antwoord.', 'Klik snel twee keer op een knop. Als je een invulveld hebt, laat het dan leeg en ga verder. Reageert je leerhulp zoals je verwacht?'],
  };
  const testExample = (index: number) => <details className="v-example"><summary>Bekijk een testvoorbeeld</summary><div className="v-callout"><strong>Zo kun je testen:</strong><p>{testExamples[route || 'algemeen'][index]}</p></div></details>;
  const move = (from: number, to: number) => { const next = [...order]; const [item] = next.splice(from, 1); next.splice(to, 0, item); setOrder(next); update({ cycleOrder: JSON.stringify(next) }); setNotice(''); };
  const materialInstruction = work.source === 'Startpakket'
    ? `Inhoud en afspraken:\n${work.material || '(Kies eerst een startpakket.)'}`
    : `Vraag me om het materiaal dat ons plan nodig heeft. ${chosen ? 'Hiervoor heb je nodig: ' + chosen.input : 'Vraag de inhoud en afspraken die bij mijn eigen idee passen.'} Wacht tot ik het materiaal heb toegevoegd. Controleer of je het kunt lezen en vraag verduidelijking als iets ontbreekt. Verzin geen ontbrekende inhoud, antwoorden of afspraken. Bouw daarna de eerste versie.`;
  const buildPrompt = `${work.source === 'Startpakket' ? 'Bouw nu een eenvoudige eerste versie' : 'Ik wil een eenvoudige eerste versie laten bouwen'} volgens ons gecontroleerde bouwplan:\n${work.plan || '(Plak hier eerst je bouwplan.)'}\n\n${materialInstruction}\n\nMaak alles in één HTML-bestand, met alle opmaak en werking inbegrepen. Het moet na het downloaden zonder internet werken, zonder extra installaties, externe diensten, accounts of persoonsgegevens. Geef het bestand als download. Als downloaden niet kan, geef de volledige code in één blok. Begin klein. Voeg nog geen extra functies toe.`;
  const brainstormPrompt = `Ik wil vibe coden: een eenvoudige interactieve tool maken die mij helpt bij het leren. Brainstorm met mij over een passende oplossing voor mijn behoefte.

Mijn leerbehoefte: ${work.need?.trim() || '[Vul hier in wat je nodig hebt om beter te leren]'}
Mijn schoolwerk: ${work.subject?.trim() || '[Vul hier je vak of onderwerp in]'}
Wat ik lastig vind: ${work.difficult?.trim() || '[Beschrijf hier wat lastig is]'}
${work.help?.trim() ? 'Mijn voorlopige idee: ' + work.help + '\n' : ''}
De eerste versie moet simpel blijven: één HTML-bestand dat lokaal in mijn browser werkt, zonder internet, extra installaties, integraties, koppelingen met andere diensten of accounts. In de tool zelf zit geen AI. De tool gebruikt alleen de inhoud die ik vooraf meegeef. Hij kan die tonen, ordenen of nakijken, maar geen nieuwe samenvattingen, hints of vragen bedenken tijdens het gebruiken.

Stel maximaal drie haalbare ideeën voor. Vertel bij elk idee hoe het mijn behoefte helpt, wat ik zelf nog doe en welk materiaal ik vooraf moet meegeven. Bijvoorbeeld vragen met antwoorden, taken met beschikbare tijd, of stappen in de juiste volgorde. Als mijn idee te groot is, maak het dan kleiner. Stel één vraag tegelijk als je nog iets moet weten. Begin nog niet met bouwen en schrijf nog geen code.`;
  const reportEntries: [string, string][] = [['Mijn gekozen leerhulp', work.solutionKind === 'eigen' ? 'Mijn eigen idee' : chosen?.title || '(niet gekozen)'], ['Materiaalkeuze', work.source || '(niet gekozen)'], ...Object.entries(fields).filter(([key]) => key !== 'material' || work.source === 'Startpakket').map(([key, label]): [string, string] => [label, work[key] || '']), ['Wat heb ik geleerd?', learningRecap], ['Gouden tips voor prompts', promptTips.map(([tip, example]) => `${tip}: “${example}”`).join('\n')]];
  const processStages = ['Behoefte', 'Oplossing', 'Bouwen', 'Testen en verbeteren'];
  const processIndex = ['intro', 'situatie', 'definitie', 'herkennen', 'spectrum'].includes(pane) ? -1
    : ['inspiratie', 'behoefte'].includes(pane) ? 0
    : ['mogelijk', 'helpen', 'brainstorm', 'kiezen', 'oplossing', 'bestaat', 'idee'].includes(pane) ? 1
    : ['materiaal', 'pakket', 'inhoud', 'cyclus', 'volgorde', 'wisselen', 'overleg', 'plan', 'bewaarplan', 'bouwen'].includes(pane) ? 2 : 3;
  const missing = Object.keys(fields).filter(key => (key !== 'material' || work.source === 'Startpakket') && !work[key]?.trim());
  const incomplete: { label: string; pane: string }[] = missing.map(key => ({ label: fields[key], pane: fieldPanes[key] }));
  if (work.quizAnswer !== '1') incomplete.push({ label: 'Beantwoord de vraag over Noors behoefte juist', pane: 'situatie' });
  if (!choiceComplete) incomplete.push({ label: 'Kies je leerhulp en controleer je eigen idee', pane: 'kiezen' });
  if (!materialComplete) incomplete.push({ label: 'Bevestig je materiaalkeuze', pane: 'pakket' });
  if (work.cycleOrder !== '[0,1,2,3,4]') incomplete.push({ label: 'Zet de bouwstappen in de juiste volgorde', pane: 'volgorde' });
  const complete = incomplete.length === 0;
  const exportReport = async () => {
    if (!complete || downloading) return;
    setDownloading(true); setNotice('Je verslag wordt gemaakt…');
    try { await downloadReport([...reportEntries, ['Volgorde-oefening', cycle.join('\n')], ...timelineEntries()]); setNotice('PDF aangemaakt. Dien je PDF én je losse HTML-bestand in via Smartschool.'); }
    catch { setNotice('PDF downloaden lukte niet. Probeer opnieuw of open en kopieer je volledige verslag.'); }
    finally { setDownloading(false); }
  };
  return <div ref={rootRef} className="vibe" data-pane={pane} data-step-complete={pane === 'situatie' ? String(needAnswer === 1) : pane === 'kiezen' ? String(choiceComplete) : pane === 'oplossing' ? String(solutionComplete) : pane === 'volgorde' ? String(order.every((item, i) => item === i)) : pane === 'pakket' ? String(materialComplete) : undefined} data-step-hint={pane === 'kiezen' ? (!work.solutionKind ? 'Kies een hulpmiddel om verder te gaan.' : 'Vink beide checks aan bij je eigen idee.') : pane === 'oplossing' ? (choiceComplete ? 'Beschrijf je oplossing om verder te gaan.' : 'Kies eerst je hulpmiddel en controleer je eigen idee.') : pane === 'volgorde' ? 'Zet de stappen in de juiste volgorde om verder te gaan.' : pane === 'pakket' ? 'Kies Eigen materiaal of klik op Gebruik dit startpakket om verder te gaan.' : undefined}>
    <aside className="v-process" aria-label="Waar ben je in het bouwproces?">{processIndex === -1 ? <strong>Kennismaking</strong> : <ol>{processStages.map((stage, i) => <li key={stage} aria-current={i === processIndex ? 'step' : undefined}><span className="v-process-number">{i + 1}</span> {stage}</li>)}</ol>}</aside>
    {pane === 'intro' && columns(<><p className="v-lead">Je maakt met AI bijvoorbeeld een quiz, planner of tijdlijn die jou helpt bij je schoolwerk. Jij bedenkt wat je nodig hebt. AI helpt het bouwen.</p><div className="v-tags"><span>± 70 minuten</span><span>2e en 3e graad · alle finaliteiten</span><span>Geen programmeerkennis nodig</span></div></>, <><div className="v-grid v-intro"><section><h3><svg className="v-intro-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M4 7h10m-3-3 3 3-3 3M20 17H10m3-3-3 3 3 3"/><circle cx="5" cy="17" r="2"/><circle cx="19" cy="7" r="2"/></svg><span>Wat gaan we doen?</span></h3><p>Eerst een leerprobleem kiezen. Dan met AI iets maken, uitproberen en verbeteren.</p></section><section><h3><svg className="v-intro-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="m3 9 9-5 9 5-9 5-9-5Zm4 3v5c3 3 7 3 10 0v-5m4-3v7"/></svg><span>Wat leer je?</span></h3><p>Goed beschrijven wat je nodig hebt en kritisch controleren of het resultaat helpt en klopt.</p></section><section><h3><svg className="v-intro-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><rect x="4" y="4" width="16" height="12" rx="2"/><path d="m4 16-2 4h20l-2-4M9 20h6"/></svg><span>Wat heb je nodig?</span></h3><p>Een laptop, internet, je leerstof en een toegelaten AI-tool, zoals Copilot met je schoolaccount. Geen leerstof bij de hand? Wij helpen je.</p></section><section><h3><svg className="v-intro-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9l-6-6Zm0 0v6h6m-12 6 3 3 5-5"/></svg><span>Wat lever je op?</span></h3><p>Je eigen leerhulp en een PDF-verslag voor Smartschool. Zelf code schrijven of online publiceren leren we hier nog niet.</p></section></div></>)}
    {pane === 'situatie' && <div className="v-noor-layout"><div className="v-noor-story"><p>Noor leert Engelse woorden voor een toets. In haar woordenlijst staan het Engelse woord en de vertaling naast elkaar.</p><blockquote>“Ik zie de vertaling meteen. Daardoor weet ik niet of ik het woord zelf zou kennen.”</blockquote></div><div className="v-noor-question"><fieldset className={choiceStyles.group}><legend className={choiceStyles.question}>Wat heeft Noor nodig om beter te leren?</legend><div className="v-noor-options">{['Een mooie website', 'Zichzelf testen zonder de vertaling te zien', 'AI die haar huiswerk maakt'].map((answer, i) => <label key={answer} className={choiceStyles.option}><input type="radio" className={choiceStyles.radio} name="v-noor-need" checked={needAnswer === i} onChange={() => { setNeedAnswer(i); update({ quizAnswer: String(i) }); }} /><span>{answer}</span></label>)}</div></fieldset><div className="v-noor-feedback" role="status">{needAnswer !== null && <p className={`v-feedback ${needAnswer === 1 ? 'v-feedback-correct' : 'v-feedback-wrong'}`}>{['✕ Nog niet. Een mooie website lost haar leerprobleem niet vanzelf op. Wat wil Noor zelf kunnen oefenen?', '✓ Juist! Noor wil eerst zelf nadenken en daarna haar antwoord controleren. Dat is haar leerbehoefte.', '✕ Nog niet. Als AI de antwoorden geeft, weet Noor nog niet of ze de woorden zelf kent.'][needAnswer]}</p>}</div></div></div>}
    {pane === 'definitie' && columns(<><p>Noor bedenkt een oplossing: <strong>een kleine woordenquiz die de vertaling verbergt tot ze zelf heeft geantwoord.</strong> Maar ze kan niet programmeren.</p><p>Zo software maken met AI, zonder alle code zelf te lezen of te begrijpen, noemen we <strong>vibe coden</strong>.</p><details><summary>Waar komt die naam vandaan?</summary><p>AI-onderzoeker Andrej Karpathy introduceerde de term begin 2025 voor bouwen met AI zonder de code zelf te lezen. De term wordt ook breder gebruikt.</p><a href="https://simonwillison.net/2025/Mar/19/vibe-coding/" target="_blank" rel="noreferrer">Meer over de oorsprong</a></details></>, <><div className="v-callout"><p>Ze vraagt AI: “Maak een quiz met mijn Engelse woorden. Toon één woord tegelijk en laat mij eerst de vertaling invullen.”</p><strong>Noor beschrijft wat ze wil. AI schrijft de code. Noor probeert de quiz uit en vraagt verbeteringen.</strong></div></>)}
    {pane === 'herkennen' && <><p><strong>Hoe gaat Noor van haar behoefte naar een bruikbare quiz?</strong> Klik op de vier stappen. Jij volgt straks dezelfde weg met je eigen idee.</p><div className="v-discover-process"><div className="v-process-picks">{['1. Behoefte', '2. Oplossing bedenken', '3. Bouwen', '4. Testen en verbeteren'].map((label, i) => <div className="v-flow-option" key={label}><button aria-pressed={selected === i} onClick={() => setSelected(i)}>{label}</button>{i < 3 ? <span className="v-flow-arrow" aria-hidden="true">↓</span> : <span className="v-iteration-loop"><svg viewBox="0 0 76 62" fill="none" aria-hidden="true"><path d="M2 34H38C70 34 70 8 38 8H2M10 1 2 8l8 7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg><span>itereren</span></span>}</div>)}</div><div className="v-callout" aria-live="polite">{['Noor wil Engelse woorden leren. Ze ziet de vertaling te snel. Ze heeft nodig: eerst zelf nadenken en daarna haar antwoord controleren.', 'Zou een digitaal hulpmiddel helpen? Noor denkt aan een woordenquiz die de vertaling verbergt. Ze kijkt of zoiets al bestaat en bepaalt wat haar quiz moet doen.', 'Noor overlegt met AI en geeft haar woordenlijst mee. AI bouwt een kleine eerste versie van haar quiz.', 'Noor probeert de quiz uit. Blijft de vertaling verborgen? Kloppen de antwoorden? Ze vraagt verbeteringen en test opnieuw. Dat blijft ze herhalen.'][selected]}</div></div><p className="v-small">Hierna ontdek je hoe klein of uitgebreid zo’n quiz kan worden.</p></>}
    {pane === 'spectrum' && <><p>Met vibe coden kun je klein beginnen en later uitgebreide apps bouwen. <strong>Vandaag maken we een eenvoudige eerste versie.</strong> Klik op de mogelijkheden om ze te ontdekken.</p><div className="v-spectrum-layout"><div className="v-spectrum-scale" aria-label="Van eenvoudig bovenaan naar complexer onderaan"><span>Eenvoudig</span><span className="v-spectrum-shaft" aria-hidden="true"/><span>Complexer</span></div><div className="v-spectrum">{['Op jouw computer', 'Online delen', 'Andere diensten gebruiken', 'Gegevens bewaren'].map((name, i) => <button key={name} aria-pressed={selected === i} onClick={() => setSelected(i)}>{i + 1}. {name}{i === 0 && <small>Dit maken we vandaag</small>}</button>)}</div><div className="v-callout" aria-live="polite">{selected === 0 && <><strong>Een interactieve pagina op je laptop</strong><p>Je opent een bestand in je browser. Het hoeft niet online te staan.</p><p><strong>Bijvoorbeeld:</strong> Noors woordenquiz toont een woord. De vertaling verschijnt pas nadat ze zelf heeft geantwoord.</p></>}{selected === 1 && <><strong>Een publieke website</strong><p>Je zet je website online. Anderen kunnen die via een link openen en gebruiken.</p><p><strong>Voorbeeld:</strong> Een klasgenoot opent Noors woordenquiz via een link.</p></>}{selected === 2 && <><strong>Andere diensten toevoegen</strong><p>Je verbindt je website met bijvoorbeeld een kaartendienst of een AI-chatbot.</p><p><strong>Voorbeeld:</strong> Noor voegt een AI-chatbot toe die een hint of voorbeeldzin geeft.</p><p className="v-small">Een chatbot vraagt meer werk en afspraken over kosten en privacy.</p></>}{selected === 3 && <><strong>Een databank koppelen</strong><p>Je bewaart gegevens online, bijvoorbeeld accounts en leerresultaten.</p><p><strong>Voorbeeld:</strong> Noors quiz onthoudt moeilijke woorden, ook als ze later op een andere computer verdergaat.</p><p className="v-small">Alleen op dezelfde laptop iets onthouden kan ook zonder databank.</p></>}</div></div><p className="v-small">Dit zijn enkele voorbeelden. Er zijn nog veel meer mogelijkheden en je kunt ze combineren.</p></>}
    {pane === 'inspiratie' && columns(<><p><strong>Denk aan je eigen schoolwerk.</strong> Wat vind jij lastig bij het leren of voorbereiden?</p><p>Deze kaartjes zijn inspiratie. Klik op een kaartje om een voorbeeld te bekijken. Je eigen situatie mag helemaal anders zijn.</p><p className="v-small">Op het volgende scherm beschrijf je je eigen situatie. Je hoeft hier niets te kiezen of over te nemen.</p></>, <><div className="v-grid v-situations">{learningSituations.map((situation, i) => <button key={situation.title} aria-pressed={selected === i} onClick={() => setSelected(i)}>{situation.title}</button>)}</div><div className="v-callout" aria-live="polite"><p><strong>Bijvoorbeeld:</strong> {learningSituations[selected].text}</p><strong>Wat heb ik in dit voorbeeld nodig?</strong><p>{learningSituations[selected].need}</p></div></>)}
    {pane === 'behoefte' && columns(<><p><strong>Beschrijf je eigen situatie in je eigen woorden.</strong> Denk eerst aan wat je nodig hebt om te leren. De oplossing bedenken we daarna.</p></>, <>{field('subject', 'Bijvoorbeeld: Engelse woorden voor een toets.', 2)}{field('difficult', 'Bijvoorbeeld: ik zie de vertaling al vóór ik zelf heb nagedacht.', 2)}{field('need', 'Bijvoorbeeld: ik wil controleren of ik de woorden ken zonder de vertaling te zien.', 2)}</>)}
    {pane === 'bestaat' && <><p>Je hoeft niet voor alles zelf iets te bouwen.</p><div className="v-callout"><strong>Maak er een gewoonte van:</strong><p>Kijk eerst of er al een app, website of ander hulpmiddel bestaat dat doet wat jij nodig hebt.</p></div><p><strong>Voor deze opdracht gaan we verder met jouw idee.</strong> Zo leer je hoe je met AI zelf iets maakt, test en verbetert.</p></>}
    {pane === 'mogelijk' && columns(<><p><strong>Je hebt nagedacht over je behoefte. Nu zoeken we een oplossing.</strong> Die moet haalbaar zijn om deze namiddag te bouwen.</p><div className="v-scope-note"><strong>We gebruiken AI bij het bouwen.</strong><p>Je gebruikt AI terwijl je de tool maakt. Maar in de afgewerkte tool zelf zit geen AI. Die werkt alleen met de inhoud die jij vooraf meegeeft en bedenkt niets nieuws.</p></div><p className="v-small">Uitgebreidere tools kunnen meer. Vandaag beperken we ons tot deze basisversie.</p></>, <><p><strong>Bekijk hieronder enkele voorbeelden van wat vandaag mogelijk en niet mogelijk is.</strong></p><div className="v-options">{['Een samenvatting', 'Een hint', 'Quizvragen'].map((label, i) => <button key={label} aria-pressed={selected === i} onClick={() => setSelected(i)}>{label}</button>)}</div><div className="v-scope-examples" aria-live="polite"><section className="v-scope-yes"><strong>Dit is wel mogelijk in deze basisversie</strong><p>{['Je geeft vooraf een nagekeken samenvatting mee. Je leerhulp laat je de onderdelen aanklikken en bekijken.', 'Je geeft vooraf een hint en de oplossing mee. Je leerhulp toont de hint als jij op de knop klikt.', 'Je geeft vooraf vragen en de juiste antwoorden mee. Je leerhulp kiest een vraag en kijkt je antwoord na.'][selected]}</p></section><section className="v-scope-no"><strong>Dit is niet mogelijk in deze basisversie</strong><p>{['Je geeft tijdens het gebruiken een nieuwe tekst en je leerhulp schrijft zelf een samenvatting.', 'Je zit vast bij een oefening en je leerhulp bedenkt zelf een nieuwe hint.', 'Je vraagt je leerhulp om steeds nieuwe quizvragen te verzinnen.'][selected]}</p></section></div></>)}
    {pane === 'helpen' && columns(<><p>Je weet nu wat je nodig hebt. <strong>Bedenk een kleine tool die jou daarbij helpt.</strong></p><p className="v-small"><strong>Jouw behoefte:</strong> {work.need || 'Beschrijf je leerbehoefte eerst bij stap 7.'}</p><p>Bekijk de voorbeelden. Je hoeft hier nog niets te kiezen of te schrijven.</p></>, <><div className="v-grid v-tool-inspiration">{routeKeys.map((key, i) => <button key={key} aria-pressed={selected === i} onClick={() => setSelected(i)}>{routes[key].title}</button>)}</div><div className="v-callout" aria-live="polite"><p><strong>Bijvoorbeeld:</strong> {routes[routeKeys[selected]].example}</p><p><strong>Dit geef je mee:</strong> {routes[routeKeys[selected]].input}</p></div><p className="v-small">Straks kies je jouw hulpmiddel. Een eigen idee mag ook.</p></>)}
    {pane === 'kiezen' && columns(<><p><strong>Kies welk hulpmiddel je wilt maken.</strong> Kies wat past bij jouw behoefte. Je beschrijft de werking op het volgende scherm.</p><p className="v-small"><strong>Jouw behoefte:</strong> {work.need || '(nog niet ingevuld)'}</p></>, <>{choiceCards('hulpmiddel', 'Mijn hulpmiddel wordt…', [...routeKeys.map((key): [string, string] => [key, routes[key].title]), ['eigen', 'Mijn eigen idee']], work.solutionKind || '', value => update({ solutionKind: value, possible: 'Ja', route: value === 'eigen' ? '' : value, ...(work.solutionKind !== value ? { materialReady: '', basicReady: '', ...(work.source === 'Startpakket' ? { source: 'Ik heb geen geschikt materiaal', material: '', packageRoute: '', packageId: '' } : {}) } : {}) }))}{chosen && <div className="v-callout" aria-live="polite"><p><strong>Bijvoorbeeld:</strong> {chosen.example}</p><p><strong>Dit geef je mee:</strong> {chosen.input}</p></div>}{work.solutionKind === 'eigen' && <div className="v-feasibility"><strong>Vink af als dit klopt voor je eigen idee.</strong><div className="v-checks"><label><input type="checkbox" checked={work.materialReady === 'ja'} onChange={e => update({ materialReady: e.target.checked ? 'ja' : '' })} /><span>Ik heb of maak de inhoud en afspraken die mijn idee nodig heeft.</span></label><label><input type="checkbox" checked={work.basicReady === 'ja'} onChange={e => update({ basicReady: e.target.checked ? 'ja' : '' })} /><span>Mijn eerste versie werkt zonder ingebouwde AI of online diensten. Meer kan later.</span></label></div></div>}</>)}
    {pane === 'oplossing' && columns(<><p><strong>Beschrijf nu hoe jouw hulpmiddel gaat helpen.</strong> Wat doet het hulpmiddel en wat moet jij zelf nog doen?</p><p className="v-callout"><strong>Jouw behoefte:</strong> {work.need || '(nog niet ingevuld)'}</p><p><strong>Jouw hulpmiddel:</strong> {work.solutionKind === 'eigen' ? 'Mijn eigen idee' : chosen?.title || '(nog niet gekozen)'}</p>{!choiceComplete && <button onClick={() => go('kiezen')}>Ga naar mijn hulpmiddelkeuze</button>}</>, <>{field('help', 'Hoe helpt dit jou? Wat doet de leerhulp en wat doe je zelf?', 5, !choiceComplete)}<details className="v-example"><summary>Hulp nodig om je idee te beschrijven?</summary><p>Vul aan: mijn hulpmiddel toont … Ik doe zelf … Daarna krijg ik …</p><p>Bij Noor: één Engels woord verschijnt. Ik typ de vertaling. Daarna zie ik of mijn antwoord klopt. Je mag ook je eigen woorden gebruiken.</p></details></>)}
    {pane === 'brainstorm' && columns(<><p><strong>Past jouw idee bij een van de vorige voorstellen?</strong> Top! Dan kun je naar de volgende stap.</p><button onClick={() => go('kiezen')}>Ik heb al een idee → verder</button><p><strong>Nog niet helemaal gevonden wat je nodig hebt?</strong> Je kan ook brainstormen met AI over een mogelijke oplossing. Kopieer bijvoorbeeld deze prompt naar een AI-chattool die je mag gebruiken.</p>{!work.need?.trim() && <p className="v-small">Vervang eerst de tekst tussen vierkante haken door jouw behoefte en schoolwerk.</p>}<p><strong>Keer na ongeveer drie minuten terug naar dit leerpad.</strong> Klik op Volgende om jouw hulpmiddel te kiezen.</p></>, <>{prompt(brainstormPrompt, ['Vertrek van je behoefte. Vul die concreet in voordat je AI om ideeën vraagt.', 'Vraag enkele voorstellen én wat je voor elk voorstel moet meegeven.', 'Baken de mogelijkheden af en zeg dat AI nog niet mag bouwen.'])}</>)}
    {pane === 'pakket' && columns(<><p><strong>Leg het materiaal klaar dat jouw idee nodig heeft.</strong></p><p className="v-small"><strong>Voor jouw idee:</strong> {chosen?.input || 'inhoud en afspraken waarmee je leerhulp kan werken.'}</p>{choiceCards('materiaal', 'Welk materiaal ga je gebruiken?', [['Eigen materiaal', 'Mijn eigen materiaal'], ['Ik heb geen geschikt materiaal', 'Een startpakket uit dit leerpad']], work.source === 'Startpakket' ? 'Ik heb geen geschikt materiaal' : work.source || '', value => update({ source: value }))}{work.source && work.source !== 'Eigen materiaal' && <><p className="v-small">{route ? `Dit startpakket kan je gebruiken voor het type hulpmiddel dat je in stap ${stepNumber('kiezen')} koos.` : 'Kies materiaal voor je eigen idee. Deze keuze verandert je hulpmiddel niet.'} Lees de inhoud en afspraken na. Klik daarna op ‘Gebruik dit startpakket’ om je keuze te bevestigen.</p></>}</>, <>{!route && work.source && work.source !== 'Eigen materiaal' && <section className="v-package-category"><h3>1. Kies het soort startmateriaal</h3><label className="v-small" htmlFor="v-package-category">Soort startmateriaal</label><select id="v-package-category" value={packageRoute || ''} onChange={e => update({ packageRoute: e.target.value, packageId: '', source: 'Ik heb geen geschikt materiaal' })}><option value="">Kies het soort materiaal</option>{routeKeys.map(key => <option key={key} value={key}>{routes[key].title}</option>)}</select></section>}{!work.source ? <p className="v-small">Kies of je eigen materiaal of een startpakket gebruikt.</p> : work.source === 'Eigen materiaal' ? <div className="v-callout"><strong>Gebruik je eigen materiaal.</strong><p>Kies een klein begin: enkele woorden, oefeningen, taken, gebeurtenissen of stappen. Gebruik een PDF, PowerPoint, Word- of Excelbestand, foto of tekst. Je hoeft hier niets te uploaden of te beschrijven. Straks geef je het materiaal rechtstreeks aan AI.</p></div> : <>{availablePackages.length > 0 && <section className="v-package-list"><h3>{route ? 'Kies een startpakket' : '2. Kies een startpakket'}</h3><div className="v-options">{availablePackages.map(pack => <button key={pack.id} aria-pressed={chosenPackage?.id === pack.id} aria-expanded={chosenPackage?.id === pack.id} onClick={() => { if (work.packageId !== pack.id) update({ packageId: pack.id, source: 'Ik heb geen geschikt materiaal' }); }}>{pack.title}</button>)}</div></section>}{chosenPackage && <>{work.source === 'Startpakket' ? <>{field('material', 'Je kunt deze inhoud en afspraken aanpassen.', 4)}<p className="v-small">✓ Startpakket geselecteerd. De inhoud staat straks automatisch in je bouwprompt.</p></> : <><p className="v-small"><strong>{chosenPackage.title}</strong></p><pre className="v-material">{chosenPackage.material + '\n\nAfspraken om na te kijken: ' + chosenPackage.check}</pre><button onClick={() => update({ material: chosenPackage.material + '\n\nAfspraken om na te kijken: ' + chosenPackage.check, source: 'Startpakket' })}>Gebruik dit startpakket</button></>}</>}</>}</>)}
    {pane === 'cyclus' && <><p>AI maakt niet altijd meteen wat jij bedoelt.</p><div className="v-cycle">Beschrijf → laat bouwen → probeer uit → stuur bij → test opnieuw ↻</div><p><strong>Dat heet itereren:</strong> herhalen en telkens bijsturen om je resultaat beter te maken.</p><p>Je eerste versie is een begin. Test daarna opnieuw, ook wat eerder al werkte.</p></>}
    {pane === 'volgorde' && columns(<><p>Noor leert Engelse woorden. Ze wil eerst zelf nadenken en daarna pas de vertaling bekijken. Zet haar stappen in volgorde: sleep, of gebruik de pijltjes.</p></>, <><ol className="v-sort">{order.map((item, index) => <li key={item} draggable onDragStart={() => setDragged(index)} onDragOver={e => e.preventDefault()} onDrop={e => { e.preventDefault(); if (dragged !== null) move(dragged, index); setDragged(null); }}><span>{cycle[item]}</span><button aria-label={`Stap ${index + 1} omhoog`} disabled={index === 0} onClick={() => move(index, index - 1)}>↑</button><button aria-label={`Stap ${index + 1} omlaag`} disabled={index === 4} onClick={() => move(index, index + 1)}>↓</button></li>)}</ol><button onClick={() => { const ok = order.every((item, i) => item === i); update({ volgorde: order.map(i => cycle[i]).join('\n') }); setNotice(ok ? 'Juist! Na opnieuw testen kun je weer verbeteren: dat is itereren. ↻' : 'Nog niet. Eerst vraagt Noor een versie, daarna test en verbetert ze die. Probeer opnieuw.'); }}>Controleer volgorde</button><p role="status">{notice}</p></>)}
    {pane === 'wisselen' && <section className="v-two-tabs"><p className="v-attention-label">⚠ Even opletten: zo werk je verder</p><p><strong>Houd dit leerpad én een toegelaten AI-chattool open, elk in een eigen tabblad.</strong></p><ol className="v-tab-flow"><li><strong>1. In dit leerpad</strong><span>Lees de opdracht en kopieer de prompt.</span></li><li><strong>2. In je AI-chat</strong><span>Plak de prompt en voer de opdracht uit.</span></li><li><strong>3. Terug in dit leerpad</strong><span>Bewaar je resultaat als dat gevraagd wordt en ga verder.</span></li></ol><p>AI weet niet wanneer je hier verder moet. <strong>Volg de instructies van het leerpad, ook als AI blijft doorvragen.</strong></p><a href={`${import.meta.env.BASE_URL.replace(/\/$/, '')}/tools/`} target="_blank" rel="noreferrer">Bekijk welke AI-chattools je mag gebruiken ↗</a><p className="v-small">Gebruik bij Copilot je schoolaccount.</p></section>}
    {pane === 'overleg' && columns(<><p><strong>Nu overleg je met AI over jouw idee.</strong> Kopieer de prompt en plak die in een AI-chattool die je graag wilt gebruiken en mag gebruiken. Houd dit leerpad ook open.</p>{handoff('Praat ongeveer vijf minuten met AI. Kom daarna terug en klik op Volgende, ook als AI nog vragen stelt.')}<p className="v-small">Nog geen AI-tabblad? <a href={`${import.meta.env.BASE_URL.replace(/\/$/, '')}/tools/`} target="_blank" rel="noreferrer">Bekijk de toegelaten tools ↗</a></p></>, <>{prompt(`Ik wil een leerhulp maken voor mijn schoolwerk.\nMijn schoolwerk: ${work.subject || '…'}\nWat lastig is: ${work.difficult || '…'}\nWat ik nodig heb: ${work.need || '…'}\nMijn idee: ${work.help || '…'}\n\n${chosen ? 'Mijn type leerhulp: ' + chosen.title + '. Hiervoor geef ik mee: ' + chosen.input : 'Help me mijn eigen idee concreet te maken.'} Help me dit gekozen idee uit te werken tot een klein bouwplan. Als we al brainstormden, werk dan verder met mijn keuze. Stel één vraag tegelijk. Mijn eerste versie moet lokaal werken met inhoud en afspraken die ik vooraf meegeef, zonder ingebouwde AI, online diensten of accounts. Als mijn idee te groot is, help me een kleiner deel kiezen dat al helpt. Begin nog niet met bouwen.`, ['Geef context: je leerbehoefte en je idee staan al in deze prompt.', 'Laat AI eerst meedenken en één vraag tegelijk stellen.', 'Baken je eerste versie af. Laat AI helpen om een groot idee kleiner te maken.'])}</>)}
    {pane === 'plan' && columns(<><p>Kopieer de prompt en plak die in <strong>hetzelfde AI-gesprek</strong> om je bouwplan te laten samenvatten.</p>{handoff('Lees het plan in je chat kritisch. Vraag aanpassingen als het niet klopt. Kom terug zodra je plan goed zit. Op het volgende scherm bewaar je het.')}<p className="v-small">AI mag nog niet bouwen.</p></>, <>{prompt('Vat ons plan kort samen: wat wil ik leren of organiseren, wat vind ik lastig, hoe helpt mijn leerhulp, welk materiaal en welke afspraken geef ik mee en wat bouwen we in de eerste versie? Vermeld wat ik zelf moet doen. Begin nog niet met bouwen.', ['Vraag een samenvatting vóór je laat bouwen.', 'Controleer het plan: klopt de werking met je behoefte en past het bij je materiaal?', 'Zeg duidelijk wanneer AI nog niet mag bouwen.'])}</>)}
    {pane === 'bewaarplan' && columns(<p>Ga naar je AI-chat, kopieer het gecontroleerde bouwplan en kom terug om het hier te plakken. Dit bouwplan wordt opgenomen in het eindresultaat van het leerpad.</p>, field('plan', undefined, 7))}
    {pane === 'bouwen' && columns(<>{work.source === 'Startpakket' ? <p>Je startpakket staat al in de prompt. Controleer je bouwplan en kopieer de prompt naar hetzelfde AI-gesprek.</p> : <><p><strong>Kopieer de prompt naar je bestaande AI-gesprek.</strong> AI zal je eerst vragen om het materiaal voor jouw idee te geven.</p><p>Als AI erom vraagt, voeg je je afgesproken materiaal toe: een PDF, PowerPoint, Word- of Excelbestand, een duidelijke foto of geplakte tekst.</p><details><summary>Kan AI je bestand niet lezen?</summary><p>Plak een kort stukje als tekst. AI controleert eerst het materiaal en bouwt daarna je eerste versie.</p></details></>}{(!work.plan?.trim() || (work.source === 'Startpakket' && !work.material?.trim())) && <p className="v-callout v-small">Er ontbreekt nog een bouwplan of de inhoud van je startpakket. Ga eerst terug om dit aan te vullen.</p>}{handoff('Laat AI bouwen, download het bestand en kom terug om het te openen en te testen.')}</>, <>{prompt(buildPrompt, ['Geef het gecontroleerde plan en het nodige materiaal mee.', 'Vraag één volledig HTML-bestand dat lokaal werkt zonder internet of accounts.', 'Begin klein. Extra functies komen na het testen.'])}</>)}
    {pane === 'openen' && columns(<><p><strong>Je eerste versie is gemaakt. Nu open je die om te testen.</strong></p><ol><li>Download het HTML-bestand uit je AI-chat. Bewaar het in een map ‘Mijn leerhulp’.</li><li>Open het met een dubbelklik. Kies een browser als je laptop vraagt waarmee je het wilt openen.</li><li>Bewaar de eerste versie, zodat je straks kunt vergelijken.</li></ol></>, <><button onClick={() => { if (rootRef.current) celebrateMilestone(rootRef.current, 'eerste-versie'); update({ firstVersionOpened: 'ja' }); }}>{work.firstVersionOpened === 'ja' ? '✓ Mijn eerste versie is geopend' : 'Mijn eerste versie is geopend!'}</button><details name={`v-${pane}`}><summary>Ik krijg alleen code of mijn bestand opent niet</summary><p>Vraag: “Geef mij dit als één downloadbaar HTML-bestand.” Lukt dat niet? Kopieer de volledige code naar een platte-teksteditor (zoals Kladblok). Bewaar als leerhulp.html, met bestandstype ‘alle bestanden’ en UTF-8. Op een Mac kies je in Teksteditor eerst platte tekst. De naam mag niet eindigen op .html.txt.</p></details><details name={`v-${pane}`}><summary>Ik krijg een fout of bereik een limiet</summary><p>Vertel AI wat je deed en kopieer de foutmelding. Bij een limiet: bewaar je plan. Gebruik alleen een andere tool als dat mag. Lukt bouwen niet, noteer de blokkade en test het voorbeeld op het volgende scherm.</p></details></>)}
    {pane === 'voorbeeld' && columns(<><p><strong>Je eerste versie is er. We zijn nu in de testfase.</strong> Eerst oefenen we samen: in de mini-quiz zit bewust een fout. Klik twee keer op hetzelfde antwoord. Wat valt je op?</p><details name={`v-${pane}`}><summary>Wat gaat er mis? Bekijk de uitleg</summary><p>Je krijgt telkens opnieuw een punt voor hetzelfde antwoord. Een verbeteropdracht: “Laat elk antwoord maar één keer meetellen, ook bij dubbelklikken.”</p></details><p className="v-small">Hierna test je jouw eigen leerhulp met vier korte testkaarten.</p></>, <><section className="v-demo" aria-label="Interactieve voorbeeldquiz"><span className="v-demo-label">PROBEER DEZE VOORBEELDQUIZ</span><h3>Wat betekent “apple”?</h3><div className="v-options"><button onClick={() => { setSelected(selected + 1); setNotice('Correct!'); }}>Appel</button><button onClick={() => setNotice('Niet juist. Probeer Appel.')}>Peer</button></div><p role="status">{notice || 'Klik op een antwoord.'}</p><strong>Score: {selected} punt(en)</strong></section></>)}
    {pane === 'testbasis' && columns(<><p><strong>Test nu je eigen leerhulp.</strong> Probeer elke knop: starten, controleren, verdergaan en opnieuw beginnen. Vergelijk met je bouwplan.</p>{testExample(0)}</>, <>{field("basic", "Ik probeerde … Ik verwachtte … Er gebeurde …", 4)}</>)}
    {pane === 'testinhoud' && columns(<><p><strong>Controleer de inhoud van je eigen leerhulp.</strong> Vergelijk met je materiaal en afspraken. Controleer bijvoorbeeld antwoorden, datums, taken, volgordes of berekeningen. Bij een planner kijk je ook of alles in de beschikbare tijd past.</p>{testExample(1)}</>, <>{field("content", "Welke inhoud controleerde je? Waarmee? Wat ontdekte je?", 4)}</>)}
    {pane === 'testonverwacht' && columns(<><p>Kies minstens twee acties die bij jouw pagina passen.</p><div className="v-tags"><span>Niets invullen</span><span>Snel dubbelklikken</span><span>Enter indrukken</span><span>Hoofdletters / extra spaties</span></div>{testExample(2)}</>, <>{field('unexpected', 'Noteer minstens twee acties, wat je verwachtte en wat er gebeurde.', 4)}</>)}
    {pane === 'testleren' && columns(<><p>Gebruik je leerhulp een paar minuten.</p><p>Moet je zelf nadenken? Verschijnt hulp op het juiste moment? Helpt dit bij jouw behoefte: <strong>{work.need || '(nog invullen)'}</strong>?</p></>, <>{field('learning', 'Wat helpt? Wat neemt misschien te veel denkwerk over? Wat kan beter?', 4)}</>)}
    {pane === 'verbeteren' && <><div className="v-grid"><div className="v-callout"><strong>Een fout gevonden?</strong><p>Los die eerst op. Vertel AI wat je deed, wat er gebeurde en wat je verwachtte.</p></div><div className="v-callout"><strong>Geen fout gevonden?</strong><p>Bedenk wat jou nog beter helpt leren. Meer kleur of meer knoppen is niet vanzelf beter.</p></div></div><details className="v-example"><summary>Hulp nodig? Bekijk ideeën voor een verbetering</summary><div className="v-callout"><strong>Ideeën om je leerhulp te verbeteren</strong><ul>{(chosen ? chosen.tips : ['Laat hulp pas verschijnen nadat je zelf hebt nagedacht.', 'Maak duidelijk waarom een antwoord juist of fout is.']).map(tip => <li key={tip}>{tip}</li>)}</ul></div></details><p>Vraag in dezelfde AI-chat één gerichte aanpassing. Download en open de nieuwe versie. Kom terug naar dit leerpad. Test de wijziging én wat eerder al werkte.</p></>}
    {(pane === 'ronde1' || pane === 'ronde2') && columns(<><p>{pane === 'ronde1' ? 'Voer je eerste verbetering uit.' : 'Kies nu een tweede fout of verbetering die helpt bij jouw leerbehoefte.'} Bewaar elke nieuwe versie apart.</p><p className="v-callout">Vraag: “Als ik … doe, gebeurt … Ik wil … Geef het volledige aangepaste HTML-bestand als download.”</p>{handoff('Vraag de aanpassing in dezelfde chat. Download, test en kom terug om het resultaat te noteren.')}<details className="v-prompt-tips"><summary>Wat kun je hiervan leren?</summary><ul><li>Vertel wat je deed, wat er gebeurde en wat je verwachtte.</li><li>Vraag één gerichte aanpassing en het volledige bijgewerkte bestand.</li><li>Test opnieuw. Herhalen en bijsturen heet itereren.</li></ul></details></>, <>{field(pane === 'ronde1' ? 'change1' : 'change2', 'Wat was het probleem of je wens? Wat vroeg je aan AI? Wat ontdekte je bij het opnieuw testen?', 5)}</>)}
    {pane === 'terugblik' && columns(<><p className="v-callout"><strong>Je oorspronkelijke behoefte:</strong> {work.need || '(niet ingevuld)'}</p><p>Is bouwen niet gelukt? Beschrijf eerlijk waar het stopte en wat je wel hebt geleerd.</p></>, <>{field('reflection', 'Helpt je leerhulp hierbij? Wat heb je zelf beslist en gecontroleerd? Welke beperking blijft er? Wat zou je een volgende keer anders doen?', 5)}</>)}
    {pane === 'onthouden' && columns(<><p><strong>Dit kun je voortaan zelf.</strong> Je vertrekt van je behoefte, beschrijft je idee en geeft inhoud en afspraken mee.</p><p>Je laat AI eerst meedenken, bouwt klein en test zelf. Met concrete feedback stuur je bij en test je opnieuw. Dat is <strong>itereren</strong>.</p><p className="v-small">Deze tips komen mee in de PDF.</p>{field('remember', 'Welke tip wil jij onthouden voor een volgende keer?', 2)}</>, <><h3 className="v-tips-title">Gouden tips voor je prompts</h3><div className="v-cheatsheet">{promptTips.map(([tip, example]) => <details key={tip}><summary>{tip}</summary><p>“{example}”</p></details>)}</div></>)}
    {pane === 'verder' && columns(<><p><strong>Je hebt nu de basis in handen.</strong> Voor deze opdracht hoef je je leerhulp niet verder uit te breiden.</p><p>Ben je nieuwsgierig? Experimenteer later gerust verder. Voeg bijvoorbeeld één functie toe die jou echt helpt, verbeter het ontwerp of ontdek hoe je je leerhulp kunt delen.</p><p>Ook bij een groter idee volg je hetzelfde patroon. Begin klein en controleer telkens of het werkt.</p><p className="v-small"><a href="https://vibecodenvoordocenten.vercel.app/" target="_blank" rel="noreferrer">Verder lezen: Vibe Coden voor docenten ↗</a><br />Deze cursus is geschreven voor leerkrachten, maar je kunt er ook zelf inspiratie opdoen.</p></>, <ol className="v-future-cycle"><li><strong>1. Vertrek van een behoefte</strong><span>Wat zou jou helpen?</span></li><li><strong>2. Bedenk een oplossing</strong><span>Wat moet je hulpmiddel doen?</span></li><li><strong>3. Bouw een eerste versie</strong><span>Beschrijf je idee en laat AI mee bouwen.</span></li><li><strong>4. Test en verbeter</strong><span>Probeer zelf, stuur bij en test opnieuw. Blijf itereren.</span></li></ol>)}
    {pane === 'bouwtools' && columns(<><p><strong>Je kunt vibe coden met een AI-chattool, zoals je hier deed.</strong> Er bestaan ook tools die speciaal gemaakt zijn om websites en apps te bouwen.</p><p>Je beschrijft je idee in een chat. De tool maakt de bestanden en toont je het resultaat. Met nieuwe opdrachten pas je het verder aan.</p><p>Voor deze opdracht hoef je geen andere tool te gebruiken. Ontdek ze later als je wilt.</p><p className="v-small">Gebruik een tool die je van school en thuis mag gebruiken. De aanpak blijft dezelfde: behoefte, oplossing, bouwen, testen en itereren.</p></>, <div className="v-builder-tools"><section><h3>Lovable</h3><p>Beschrijf welke website of app je wilt maken. Bekijk wat Lovable bouwt en vraag gerichte aanpassingen.</p><a href="https://lovable.dev/" target="_blank" rel="noreferrer">Ontdek Lovable ↗</a></section><section><h3>Bolt</h3><p>Werk in je browser aan een website of app. Geef je idee en feedback via de chat en bekijk het resultaat.</p><a href="https://bolt.new/" target="_blank" rel="noreferrer">Ontdek Bolt ↗</a></section></div>)}
    {pane === 'verslag' && columns(<><p>Je PDF bevat je antwoorden, bouwplan, tests, verbeteringen en prompttips. De tijdlijn toont bezoek- en antwoordmomenten, geen actieve werktijd.</p><p><strong>Dien je PDF én je HTML-bestand in op Smartschool.</strong> Het HTML-bestand staat al op je laptop.</p><p className="v-small">Alles blijft in je browser tot je zelf bestanden indient.</p></>, <>{!complete ? <><p><strong>Nog aan te vullen vóór je kunt downloaden:</strong></p><ul className="v-missing">{incomplete.map(({ label, pane: target }, i) => <li key={`${target}-${i}`}>{label} <button onClick={() => go(target)}>Aanvullen</button></li>)}</ul></> : <p>Alles is ingevuld. Lees je antwoorden nog even na en download je verslag.</p>}<button disabled={!complete || downloading} onClick={() => void exportReport()}>{downloading ? 'Verslag maken…' : 'Download mijn verslag als PDF'}</button><p role="status">{notice}</p><details name={`v-${pane}`}><summary>Lees of kopieer mijn volledige verslag</summary><textarea rows={5} readOnly aria-label="Volledig verslag als tekst" value={[...reportEntries, ...timelineEntries()].map(([q,a]) => `${q}\n${a || '(nog niet ingevuld)'}`).join('\n\n')} /></details></>)}
  </div>;
}
